public class VowelCounterCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Counter impl) {
        try {
            return VowelCounterChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectCounter()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectCounter()));
        check("rejects the case-sensitive bug", false, verdict(new CaseSensitiveCounter()));
        check("rejects the counts-y-as-a-vowel bug", false, verdict(new CountsYCounter()));
        check("rejects the crash-on-null bug", false, verdict(new CrashOnNullCounter()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectCounter implements Counter {
    public int countVowels(String text) {
        if (text == null) return 0;
        int count = 0;
        for (char c : text.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) >= 0) count++;
        }
        return count;
    }
}

