/**
 * TASK: Write the checks that decide whether a Counter is correct.
 *
 * The Counter contract:
 *   countVowels(text) returns how many characters of text are vowels.
 *   The vowels are a, e, i, o, u in EITHER case. The letter y is NOT a vowel.
 *   countVowels(null) returns 0, and countVowels("") returns 0.
 *   Examples: countVowels("hello") -> 2, countVowels("AEIOU") -> 5,
 *             countVowels("Yellow Sky") -> 2
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. One broken implementation THROWS a
 * NullPointerException instead of returning 0 for null, so a crash counts as a
 * failure: wrap your calls in try/catch and return false if anything is thrown.
 *
 * null is the input most people forget. So is a capital letter. So is y.
 */
interface Counter {
    /* Provided -- do not edit. */
    int countVowels(String text);
}

public class VowelCounterChecker {

    public static boolean isCorrect(Counter impl) {
        try {
            if (impl.countVowels("hello") != 2) return false;
            if (impl.countVowels("") != 0) return false;
            if (impl.countVowels("AEIOU") != 5) return false;
            if (impl.countVowels("Yellow Sky") != 2) return false;
            if (impl.countVowels("rhythm") != 0) return false;
            if (impl.countVowels(null) != 0) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
